static int muro__sess_is_done(uint16_t key, uint16_t at, uint8_t stuck) {
  (void)key;
  if (stuck || at == 0) return 0;
  switch (at) {
    case 3: return key == 1;
    case 6: return key == 2;
    case 9: return key == 3;
    case 12: return key == 4;
    case 15: return key == 5;
    case 18: return key == 6;
    case 22: return key == 7;
    case 26: return key == 8;
    case 29: return key == 9;
    case 32: return key == 10;
    case 35: return key == 11;
    case 38: return key == 12;
    case 41: return key == 13;
    case 44: return key == 14;
    default: return 0;
  }
}

