static void muro__sess_fill(muro__sess_res *res) {
  res->done = muro__sess_is_done(res->state.key, res->state.at, res->state.stuck);
  if (res->state.stuck || res->state.at == 0) {
    muro__sess_lit(res->expected, sizeof res->expected, "done");
    return;
  }
  muro__sess_exp_at(res->state.at, &res->state, res->expected, sizeof res->expected);
}

static muro__sess_res muro__sess_word_bad(muro__sess_st st) {
  muro__sess_res bad;
  memset(&bad, 0, sizeof bad);
  bad.status = MURO_SESS_UNEXPECTED;
  bad.state = st;
  bad.step = "";
  muro__sess_lit(bad.expected, sizeof bad.expected, "word");
  return bad;
}

static const char *muro__sess_word_name(uint64_t word) {
  switch (word) {
  case muro__word_pairzdbindings_Bool_true_k: return "true";
  case muro__word_pairzdbindings_Bool_false_k: return "false";
    default: return 0;
  }
}

static muro__sess_res muro__sess_word_step(
    muro__sess_st st, int dir, int tag, uint64_t word,
    muro__sess_res (*step)(muro__sess_st, int, const muro__sess_val *)) {
  muro__sess_val value;
  memset(&value, 0, sizeof value);
  if (tag == MURO_SESS_NAT) {
    value.tag = MURO_SESS_NAT;
    value.nat = word;
    return step(st, dir, &value);
  }
  if (tag == MURO_SESS_BIT || tag == MURO_SESS_PICK) {
    if (word > 1) return muro__sess_word_bad(st);
    value.tag = tag == MURO_SESS_BIT ? (uint8_t)MURO_SESS_BIT : (uint8_t)MURO_SESS_PICK;
    value.bit = (uint8_t)word;
    return step(st, dir, &value);
  }
  if (tag == MURO_SESS_UNIT) {
    value.tag = MURO_SESS_UNIT;
    return step(st, dir, &value);
  }
  if (tag == MURO_SESS_DATA) {
    const char *ctor = muro__sess_word_name(word);
    if (!ctor) return muro__sess_word_bad(st);
    value.tag = MURO_SESS_DATA;
    value.ctor = ctor;
    return step(st, dir, &value);
  }
  return muro__sess_word_bad(st);
}

muro__sess_res muro__sess_pairzdping_init(void) {
  muro__sess_res out;
  muro__sess_res *res = &out;
  int fail = 0;
  int cap = 0;
  memset(res, 0, sizeof *res);
  res->status = MURO_SESS_OK;
  res->state.key = 1;

  res->state.at = 1;
  res->state.stuck = 0;
  (void)fail;
  (void)cap;
  if (res->state.stuck || res->state.at == 0) {
    res->state.stuck = 1;
    res->state.at = 0;
    res->state.key = 1;
  }
  res->step = muro__sess_label(res->state.key, res->state.at);
  muro__sess_fill(res);
  return out;
}

muro__sess_res muro__sess_pairzdping_step(muro__sess_st st, int dir, const muro__sess_val *value) {
  muro__sess_res out;
  muro__sess_res *res = &out;
  const muro__sess_st *saved = &st;
  (void)dir;
  (void)value;
  memset(res, 0, sizeof *res);
  res->state = st;
  if (dir != MURO_SESS_SEND && dir != MURO_SESS_RECV) {
    res->status = MURO_SESS_UNEXPECTED;
    res->step = "examples/pair-bindings.muro:14 session pair-ping: end";
    muro__sess_lit(res->expected, sizeof res->expected, "done");
    res->done = st.key == 1 ? muro__sess_is_done(st.key, st.at, st.stuck) : 0;
    return out;
  }
  if (st.key != 1) {
    res->status = MURO_SESS_UNEXPECTED;
    res->step = "examples/pair-bindings.muro:14 session pair-ping: end";
    muro__sess_lit(res->expected, sizeof res->expected, "done");
    return out;
  }
  if (st.stuck) {
    res->status = MURO_SESS_UNEXPECTED;
    res->step = muro__sess_label(st.key, st.at);
    muro__sess_lit(res->expected, sizeof res->expected, "done");
    return out;
  }
  switch (st.at) {
    case 1: {
      if (dir != MURO_SESS_RECV || !muro__sess_pay_0(value, saved)) {
        res->status = MURO_SESS_UNEXPECTED;
        res->state = *saved;
        res->step = "examples/pair-bindings.muro:14 session pair-ping: first recv (Nat * Bit)";
        muro__sess_exp_at(1, saved, res->expected, sizeof res->expected);
        res->done = muro__sess_is_done(saved->key, saved->at, saved->stuck);
      } else {
        int fail = 0;
        int cap = 0;

        res->state.at = 2;
        res->state.stuck = 0;
        if (cap) {
          res->state = *saved;
          res->status = MURO_SESS_UNEXPECTED;
          res->step = "examples/pair-bindings.muro:14 session pair-ping: first recv (Nat * Bit)";
          muro__sess_lit(res->expected, sizeof res->expected, "nat_at_most 100000");
          res->done = muro__sess_is_done(saved->key, saved->at, saved->stuck);
        } else if (fail) {
          muro__sess_exp_at(1, saved, res->expected, sizeof res->expected);
          res->state = *saved;
          res->status = MURO_SESS_UNEXPECTED;
          res->step = "examples/pair-bindings.muro:14 session pair-ping: first recv (Nat * Bit)";
          res->done = muro__sess_is_done(saved->key, saved->at, saved->stuck);
        } else {
          res->status = MURO_SESS_OK;
          res->step = "examples/pair-bindings.muro:14 session pair-ping: first recv (Nat * Bit)";
          muro__sess_fill(res);
        }
      }
      break;
    }
    case 2: {
      if (dir != MURO_SESS_SEND || !muro__sess_pay_1(value, saved)) {
        res->status = MURO_SESS_UNEXPECTED;
        res->state = *saved;
        res->step = "examples/pair-bindings.muro:14 session pair-ping: first send Nat";
        muro__sess_exp_at(2, saved, res->expected, sizeof res->expected);
        res->done = muro__sess_is_done(saved->key, saved->at, saved->stuck);
      } else {
        int fail = 0;
        int cap = 0;

        res->state.at = 3;
        res->state.stuck = 0;
        if (cap) {
          res->state = *saved;
          res->status = MURO_SESS_UNEXPECTED;
          res->step = "examples/pair-bindings.muro:14 session pair-ping: first send Nat";
          muro__sess_lit(res->expected, sizeof res->expected, "nat_at_most 100000");
          res->done = muro__sess_is_done(saved->key, saved->at, saved->stuck);
        } else if (fail) {
          muro__sess_exp_at(2, saved, res->expected, sizeof res->expected);
          res->state = *saved;
          res->status = MURO_SESS_UNEXPECTED;
          res->step = "examples/pair-bindings.muro:14 session pair-ping: first send Nat";
          res->done = muro__sess_is_done(saved->key, saved->at, saved->stuck);
        } else {
          res->status = MURO_SESS_OK;
          res->step = "examples/pair-bindings.muro:14 session pair-ping: first send Nat";
          muro__sess_fill(res);
        }
      }
      break;
    }
    case 3: {
      res->status = MURO_SESS_UNEXPECTED;
      res->state = *saved;
      res->step = "examples/pair-bindings.muro:14 session pair-ping: end";
      muro__sess_lit(res->expected, sizeof res->expected, "done");
      res->done = muro__sess_is_done(saved->key, saved->at, saved->stuck);
      break;
    }
    default:
      res->status = MURO_SESS_UNEXPECTED;
      res->step = "examples/pair-bindings.muro:14 session pair-ping: end";
      muro__sess_lit(res->expected, sizeof res->expected, "done");
      break;
  }
  return out;
}

muro__sess_res muro__sess_pairzdping_step_word(muro__sess_st st, int dir, int tag, uint64_t word) {
  return muro__sess_word_step(st, dir, tag, word, muro__sess_pairzdping_step);
}

int muro__sess_pairzdping_done(muro__sess_st st) {
  if (st.key != 1) return 0;
  return muro__sess_is_done(st.key, st.at, st.stuck);
}

const char *muro__sess_pairzdping_at(muro__sess_st st) {
  if (st.key != 1) return "examples/pair-bindings.muro:14 session pair-ping: end";
  return muro__sess_label(st.key, st.at);
}

void muro__sess_pairzdping_expected(muro__sess_st st, char *buf, size_t n) {
  if (!buf || n == 0) return;
  if (st.key != 1 || st.stuck || st.at == 0) {
    muro__sess_lit(buf, n, "done");
    return;
  }
  muro__sess_exp_at(st.at, &st, buf, n);
}

